query ConsultarLibro($id: ID!) {
  book(id: $id) {
    title
    status
    author { name }
  }
}

query ListarLibros(
  $filter: BookFilterInput
  $page: PageInput
) {
  books(filter: $filter, page: $page) {
    items { id title author { name } }
    pageInfo {
      page pageSize totalItems
      totalPages hasNextPage
    }
  }
}

mutation CrearLibro($input: CreateBookInput!) {
  createBook(input: $input) {
    id
    title
    status
    author { name }
  }
}

mutation CambiarEstado($id: ID!, $status: BookStatus!) {
  updateBookStatus(id: $id, status: $status) {
    id
    title
    status
  }
}

mutation CrearLibroInvalido($input: CreateBookInput!) {
  createBook(input: $input) { id title }
}

query ComprobarLimite($page: PageInput) {
  books(page: $page) {
    items { id title }
    pageInfo { pageSize }
  }
}

query ConsultarInexistente($id: ID!) {
  book(id: $id) { id title }
}

query ListarSoloTitulos($page: PageInput) {
  books(page: $page) {
    items { id title }
    pageInfo { totalItems }
  }
}
